import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
}

export function kindFromCode(code: string): OrderEventKind | undefined {
  return (Object.keys(KIND_CODE) as OrderEventKind[]).find((k) => KIND_CODE[k] === code);
}
import { Notification } from "../domain/notification";
import { messageKey } from "./keys";
import { MqpubClient, PublishResult, WireMessage } from "./mqpubClient";
import { encodePayload } from "./payloadCodec";

/** 발송 회차 하나의 알림을 한 배치로 발행한다(회차 단위 순서·원자성). */
export class AlertPublisher {
  constructor(
    private readonly client: MqpubClient,
    private readonly topic: string,
    private readonly keyNamespace: string,
  ) {}

  toWire(n: Notification): WireMessage {
    return { key: messageKey(this.keyNamespace, n.kind, n.orderNo), payload: encodePayload(n) };
  }

  publishRun(notifications: Notification[]): PublishResult {
    return this.client.publish(this.topic, notifications.map((n) => this.toWire(n)));
  }
}
import { spawnSync } from "child_process";

export interface WireMessage {
  key: string;
  payload: string;
}

export interface PublishResult {
  accepted: number;
  batch: number;
}

export interface ConsumedMessage {
  offset: number;
  key: string;
  payload: string;
}

export class MqpubError extends Error {
  constructor(readonly code: string, readonly exitStatus: number | null) {
    super(`mqpub ${code} (exit ${exitStatus})`);
  }
}

/** 사내 메시지 발행 CLI(mqpub 3.x) 래퍼 */
export class MqpubClient {
  constructor(private readonly bin: string, private readonly spoolDir: string) {}

  private run(args: string[], input?: string): string {
    const r = spawnSync(this.bin, args, {
      input,
      encoding: "utf8",
      env: { ...process.env, MQPUB_SPOOL: this.spoolDir },
    });
    if (r.error) throw r.error;
    if (r.status !== 0) {
      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
      throw new MqpubError(code, r.status);
    }
    return r.stdout;
  }

  /** 메시지들을 한 배치로 발행한다. */
  publish(topic: string, messages: WireMessage[]): PublishResult {
    if (messages.length === 0) return { accepted: 0, batch: 0 };
    const body = messages.map((m) => `${m.key}\t${m.payload}`).join("\n") + "\n";
    const out = this.run(["publish", "-t", topic], body);
    const m = /^accepted (\d+) batch (\d+)$/m.exec(out);
    if (!m) throw new MqpubError("unparsed-output", 0);
    return { accepted: Number(m[1]), batch: Number(m[2]) };
  }

  /** offset 부터 끝까지 읽는다. */
  consume(topic: string, fromOffset: number): ConsumedMessage[] {
    const out = this.run(["consume", "-t", topic, "-o", String(fromOffset)]);
    const rows: ConsumedMessage[] = [];
    for (const line of out.split("\n")) {
      if (line === "") continue;
      const [off, key, ...rest] = line.split("\t");
      rows.push({ offset: Number(off), key, payload: rest.join("\t") });
    }
    return rows;
  }
}
import { Notification } from "../domain/notification";
import { isEventKind } from "../domain/order";

const VERSION = 2;
const MAX_PAYLOAD = 900;

interface WirePayload {
  v: number;
  o: string;
  c: string;
  k: string;
}

/** 탭·개행·제어문자는 와이어 형식(<key>TAB<payload>)을 깨므로 제거한다. */
function scrub(s: string): string {
  return s.replace(/[\u0000-\u001f\u007f]/g, "");
}

export function encodePayload(n: Notification): string {
  const body: WirePayload = { v: VERSION, o: scrub(n.orderNo), c: scrub(n.customerId), k: n.kind };
  const json = JSON.stringify(body);
  if (json.length > MAX_PAYLOAD) throw new Error("payload too large");
  return json;
}

export function decodePayload(raw: string): Notification | null {
  let body: Partial<WirePayload>;
  try {
    body = JSON.parse(raw) as Partial<WirePayload>;
  } catch {
    return null;
  }
  if (body.v !== VERSION && body.v !== 1) return null;
  if (typeof body.o !== "string" || typeof body.c !== "string" || !isEventKind(body.k)) return null;
  return { orderNo: body.o, customerId: body.c, kind: body.k };
}

