import { validateCustomer, Customer } from "../domain/customer";
import { Channel, Order, OrderEventKind, isEventKind } from "../domain/order";
import { CustomerRepository } from "../repository/customerRepository";
import { OrderRepository } from "../repository/orderRepository";

export interface PlaceOrderInput {
  customerId: string;
  channel?: Channel;
  partner?: string;
  placedOn: string;
}

export class OrderService {
  constructor(private readonly customers: CustomerRepository, private readonly orders: OrderRepository) {}

  registerCustomer(input: unknown): Customer {
    return this.customers.save(validateCustomer(input));
  }

  placeOrder(input: PlaceOrderInput): Order {
    if (!this.customers.find(input.customerId)) throw new Error("unknown customer");
    const channel = input.channel ?? "direct";
    if (channel !== "direct" && channel !== "market") throw new Error("invalid channel");
    return this.orders.create(input.customerId, channel, input.placedOn, input.partner);
  }

  recordEvent(orderNo: string, kind: unknown): { orderNo: string; kind: OrderEventKind; seq: number } {
    if (!isEventKind(kind)) throw new Error("invalid event kind");
    const seq = this.orders.addEvent(orderNo, kind);
    return { orderNo, kind, seq };
  }
}
import { Channel, Order, OrderEventKind, formatOrderNo } from "../domain/order";

export interface PendingEvent {
  orderNo: string;
  customerId: string;
  kind: OrderEventKind;
  seq: number;
}

export class OrderRepository {
  private readonly orders = new Map<string, Order>();
  /** 채널·제휴사·주문일별 일련번호 */
  private readonly counters = new Map<string, number>();
  private eventSeq = 0;

  create(customerId: string, channel: Channel, placedOn: string, partner?: string): Order {
    const counterKey = `${channel}|${partner ?? ""}|${placedOn}`;
    const next = (this.counters.get(counterKey) ?? 0) + 1;
    this.counters.set(counterKey, next);
    const order: Order = {
      orderNo: formatOrderNo(channel, placedOn, next, partner),
      customerId,
      channel,
      partner,
      placedOn,
      events: [],
    };
    this.orders.set(order.orderNo, order);
    return order;
  }

  find(orderNo: string): Order | undefined {
    return this.orders.get(orderNo);
  }

  addEvent(orderNo: string, kind: OrderEventKind): number {
    const order = this.orders.get(orderNo);
    if (!order) throw new Error("order not found");
    const seq = ++this.eventSeq;
    order.events.push({ kind, seq, dispatched: false });
    return seq;
  }

  /** 아직 발송 회차에 실리지 않은 이벤트를 기록 순으로 꺼내고 실린 것으로 표시한다. */
  takePending(): PendingEvent[] {
    const out: PendingEvent[] = [];
    for (const o of this.orders.values()) {
      for (const e of o.events) {
        if (e.dispatched) continue;
        e.dispatched = true;
        out.push({ orderNo: o.orderNo, customerId: o.customerId, kind: e.kind, seq: e.seq });
      }
    }
    return out.sort((a, b) => a.seq - b.seq);
  }
}
import { DeliveredAlert } from "../domain/notification";
import { OrderEventKind } from "../domain/order";
import { MqpubClient } from "../messaging/mqpubClient";
import { decodePayload } from "../messaging/payloadCodec";
import { CustomerRepository } from "../repository/customerRepository";
import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
import { SmsGateway } from "./smsGateway";
import { renderAlert } from "./templates";

export interface DrainResult {
  read: number;
  delivered: DeliveredAlert[];
  failed: { orderNo: string; kind: OrderEventKind; reason: string }[];
}

/**
 * 알림 토픽 소비자. 마지막으로 읽은 위치 다음부터 읽어 문자를 보낸다.
 * 같은 키가 다시 전달되면(재처리·재기동) 두 번 보내지 않는다.
 */
export class AlertConsumer {
  private nextOffset = 0;
  private readonly handledKeys = new Set<string>();

  constructor(
    private readonly client: MqpubClient,
    private readonly topic: string,
    private readonly customers: CustomerRepository,
    private readonly gateway: SmsGateway,
    private readonly log: DeliveryLogRepository,
    private readonly senderId: string,
    private readonly limit: number,
  ) {}

  position(): number {
    return this.nextOffset;
  }

  drain(runId: number): DrainResult {
    const rows = this.client.consume(this.topic, this.nextOffset).slice(0, this.limit);
    const result: DrainResult = { read: rows.length, delivered: [], failed: [] };
    for (const row of rows) {
      this.nextOffset = row.offset + 1;
      if (this.handledKeys.has(row.key)) continue;
      this.handledKeys.add(row.key);

      const n = decodePayload(row.payload);
      if (!n) {
        result.failed.push({ orderNo: "?", kind: "PAID", reason: "bad-payload" });
        continue;
      }
      const customer = this.customers.find(n.customerId);
      if (!customer) {
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: "unknown-customer" });
        continue;
      }
      const receipt = this.gateway.send(this.senderId, customer.phone, renderAlert(n.kind, customer.name, n.orderNo));
      if (!receipt.ok) {
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: receipt.reason ?? "sms-failed" });
        continue;
      }
      const d: DeliveredAlert = {
        runId,
        orderNo: n.orderNo,
        customerId: n.customerId,
        kind: n.kind,
        phone: customer.phone,
        receiptId: receipt.receiptId ?? "",
      };
      this.log.append(d);
      result.delivered.push(d);
    }
    return result;
  }
}
import { formatOrderNo } from "../src/domain/order";
import { decodePayload, encodePayload } from "../src/messaging/payloadCodec";
import { renderAlert } from "../src/notifier/templates";
import { clip, displayWidth, maskMobile, normalizeMobile } from "../src/util/format";
import { eq, run, test } from "./harness";

test("mobile numbers normalize to 11 digits", () => {
  eq(normalizeMobile("010-1234-5678"), "01012345678", "dashes");
  eq(normalizeMobile("+82 10 1234 5678"), "01012345678", "country code");
  eq(normalizeMobile("8201012345678"), null, "country code with trunk zero is rejected");
  eq(normalizeMobile("011-123-4567"), "01101234567", "old 10-digit");
  eq(normalizeMobile("02-123-4567"), null, "landline");
  eq(maskMobile("01012345678"), "010-****-5678", "mask");
});

test("order numbers follow the channel format", () => {
  eq(formatOrderNo("direct", "2026-10-07", 42), "O261007-00042", "direct");
  eq(formatOrderNo("market", "2026-10-07", 123, "GMKT"), "M-GMKT-261007-000123", "market");
});

test("payload round-trips and strips control characters", () => {
  const raw = encodePayload({ orderNo: "O261007-00042\t", customerId: "C1001", kind: "SHIPPED" });
  eq(raw.includes("\t"), false, "no tab on the wire");
  eq(decodePayload(raw), { orderNo: "O261007-00042", customerId: "C1001", kind: "SHIPPED" }, "decode");
  eq(decodePayload("{"), null, "garbage");
  eq(decodePayload('{"v":9,"o":"x","c":"y","k":"PAID"}'), null, "unknown version");
});

test("alert text fits the sms width", () => {
  const t = renderAlert("DELIVERED", "김하늘", "M-GMKT-261007-000123");
  eq(displayWidth(t) <= 80, true, "width");
  eq(clip("가나다라", 5), "가나…", "clip");
});

run();
import { CustomerRepository } from "../src/repository/customerRepository";
import { OrderRepository } from "../src/repository/orderRepository";
import { planNotifications } from "../src/service/notificationPlanner";
import { eq, run, test } from "./harness";

function setup() {
  const customers = new CustomerRepository();
  customers.save({ id: "C1", name: "가", phone: "010-1111-0001", smsOptIn: true });
  customers.save({ id: "C2", name: "나", phone: "010-1111-0002", smsOptIn: false });
  const orders = new OrderRepository();
  return { customers, orders };
}

test("repeated identical events in one run produce one alert", () => {
  const { customers, orders } = setup();
  const o = orders.create("C1", "direct", "2026-10-09");
  orders.addEvent(o.orderNo, "SHIPPED");
  orders.addEvent(o.orderNo, "SHIPPED");
  orders.addEvent(o.orderNo, "DELIVERED");
  const plan = planNotifications(orders.takePending(), customers);
  eq(plan.notifications.map((n) => n.kind), ["SHIPPED", "DELIVERED"], "kinds");
});

test("opt-out customers are skipped and counted", () => {
  const { customers, orders } = setup();
  orders.addEvent(orders.create("C2", "direct", "2026-10-09").orderNo, "PAID");
  orders.addEvent(orders.create("C1", "direct", "2026-10-09").orderNo, "PAID");
  const plan = planNotifications(orders.takePending(), customers);
  eq(plan.skippedOptOut, 1, "skipped");
  eq(plan.notifications.map((n) => n.customerId), ["C1"], "kept");
});

test("pending events are taken once, in recorded order", () => {
  const { orders } = setup();
  const a = orders.create("C1", "direct", "2026-10-09").orderNo;
  const b = orders.create("C1", "market", "2026-10-09", "ELVN").orderNo;
  orders.addEvent(b, "PAID");
  orders.addEvent(a, "PAID");
  eq(orders.takePending().map((e) => e.orderNo), [b, a], "order");
  eq(orders.takePending(), [], "second take");
});

run();

