import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub 3.x는 한 배치 안에서 키의 앞 16바이트가 같으면 첫 메시지만 저장하고 나머지는
 * 오류 없이 버린다(같은 날 주문번호·같은 제휴사 주문끼리 충돌). 그래서 결정적 해시 12자를
 * 키 맨 앞에 두어 앞 16바이트가 메시지마다 달라지게 한다. 해시는 논리 키에서만 계산하므로
 * 같은 알림은 항상 같은 키가 되어 재처리 시 소비 측 중복 방지가 그대로 동작한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const tag = createHash("sha256").update(logical).digest("hex").slice(0, 12);
  return `${tag}:${logical}`;
}

